example_solution:
var VALID_NUCLEOTIDES = ["A","C","G","T"]

class Nucleotide {
  static zeroCounts { { "A": 0, "C": 0, "G": 0, "T": 0} }
  static count(strand) {
    var counts = zeroCounts
    strand.each { |n|
      if (!VALID_NUCLEOTIDES.contains(n)) Fiber.abort("Invalid nucleotide in strand")
      counts[n] = counts[n] + 1
    }
    return counts
  }
}

test_code:
import "wren-testie/testie" for Testie, Expect
import "./nucleotide-count" for Nucleotide

Testie.test("count nucleotides") { |do, skip|
  do.test("empty strand") {
    Expect.value(Nucleotide.count("")).toEqual({ "A": 0, "C": 0, "G": 0, "T": 0})
  }

  skip.test("can count one nucleotide in single-character input") {
    Expect.value(Nucleotide.count("G")).toEqual({ "A": 0, "C": 0, "G": 1, "T": 0})
  }

  skip.test("strand with repeated nucleotide") {
    Expect.value(Nucleotide.count("GGGGGGG")).toEqual({ "A": 0, "C": 0, "G": 7, "T": 0})
  }

  skip.test("strand with multiple nucleotides") {
    Expect.value(
      Nucleotide.count(
        "AGCTTTTCATTCTGACTGCAACGGGCAATATGTCTCTGTGTGGATTAAAAAAAGAGTGTCTGATAGCAGC"
      )
    ).toEqual({ "A": 20, "C": 12, "G": 17, "T": 21})
  }

  skip.test("strand with invalid nucleotides") {
    Expect.that {
      Nucleotide.count("AGXXACT")
    }.abortsWith("Invalid nucleotide in strand")
  }
}
